def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        safe_bid = DAILY_SALARY * 0.35
        if hp <= 3 or no_water >= 1:
            safe_bid = DAILY_SALARY * 0.7
        return float(min(budget, safe_bid))

    capacity = supply / float(WATER_REQ)
    tight = capacity <= 1.45
    medium = capacity <= 1.8

    opp_bids = []
    urgent_bids = []
    rich_pressure = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        prev_bid = None
        if prev:
            prev_bid = prev.get('bid')
        if prev_bid is not None:
            opp_bids.append(float(prev_bid))
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
                urgent_bids.append(float(prev_bid))
            if opp.get('budget', 0) > DAILY_SALARY * 3:
                rich_pressure.append(float(prev_bid))

    highest_prev = max(opp_bids) if opp_bids else 0.0
    urgent_prev = max(urgent_bids) if urgent_bids else highest_prev
    rich_prev = max(rich_pressure) if rich_pressure else highest_prev

    if hp <= 2 or no_water >= 2:
        bid = max(DAILY_SALARY * 0.95, urgent_prev + 3.0)
    elif hp <= 4 or no_water >= 1:
        if tight:
            bid = max(DAILY_SALARY * 0.82, urgent_prev + 2.0)
        else:
            bid = max(DAILY_SALARY * 0.62, highest_prev * 0.72)
    else:
        if tight:
            bid = max(DAILY_SALARY * 0.58, rich_prev + 1.5)
        elif medium:
            bid = max(DAILY_SALARY * 0.46, highest_prev * 0.58)
        else:
            bid = DAILY_SALARY * 0.28

    days_left = 11 - day
    reserve_target = max(0.0, (days_left - 1) * DAILY_SALARY * 0.42)
    spend_cap = budget - reserve_target
    if hp <= 3 or no_water >= 1:
        spend_cap = budget - max(0.0, (days_left - 1) * DAILY_SALARY * 0.28)
    if spend_cap <= 0:
        spend_cap = min(budget, DAILY_SALARY * 0.45)
        if hp <= 3 or no_water >= 1:
            spend_cap = min(budget, DAILY_SALARY * 0.75)

    bid = min(bid, spend_cap)
    bid = min(bid, budget)

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate previous_trace only
    prev_bids = []
    prev_bid_by_agent = {}
    for oid, o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                bval = float(b)
            except Exception:
                continue
            prev_bids.append(bval)
            prev_bid_by_agent[oid] = bval

    # Base bid pressure from yesterday
    if prev_bids:
        highest_prev = max(prev_bids)
        second_prev = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev
        # If someone clearly overpaid, we shade slightly to avoid bidding into their price.
        if highest_prev >= DAILY_SALARY * 0.95:
            target = max(DAILY_SALARY * 0.65, second_prev + 5.0)
        elif highest_prev >= DAILY_SALARY * 0.75:
            target = max(DAILY_SALARY * 0.55, highest_prev * 0.85)
        else:
            # Otherwise match the market a bit above the top to secure water.
            target = max(DAILY_SALARY * 0.5, highest_prev + 10.0)
    else:
        target = DAILY_SALARY * 0.55

    # Adjust for our health and need
    if my_hp <= 2.0:
        target = max(target, DAILY_SALARY * 0.9)
    elif my_hp <= 4.0:
        target = max(target, DAILY_SALARY * 0.7)

    # If we've already gone without water, increase urgency
    if my_no_water_days >= 1:
        target = max(target, DAILY_SALARY * (0.65 + 0.1 * min(3, my_no_water_days)))

    # Supply-aware shading: higher supply reduces urgency/price
    # We don't know exact allocation mechanics; use supply as a proxy for competitive intensity.
    supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if MAX_SUPPLY > MIN_SUPPLY else 0.5
    # When supply is high, shade down a bit.
    target *= (0.95 - 0.1 * supply_norm)

    # Ensure we never exceed our budget.
    bid = max(0.0, min(my_budget, target))

    # If budget is extremely low, still bid something to try to avoid starvation.
    if my_budget <= DAILY_SALARY * 0.15:
        bid = max(0.0, min(my_budget, DAILY_SALARY * 0.25))

    # Small deterministic nudge by day to avoid exact ties.
    bid += float((day % 3) - 1) * 1.5
    bid = max(0.0, min(my_budget, bid))

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.2)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    avg_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else DAILY_SALARY

    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 1.2)

    target_bid = avg_bid * 1.05
    if target_bid > DAILY_SALARY * 0.9:
        target_bid = DAILY_SALARY * 0.9

    return min(my_status['budget'], max(target_bid, DAILY_SALARY * 0.4))
